def check_pending_return_requests(report):
    """
    Check for pending return requests in the given report.

    Args:
        report (dict): The report containing sales and return data.

    Returns:
        bool: True if there are pending return requests, False otherwise.
        int: The number of pending return requests.
    """
    pending_returns = report.get("returns", {}).get("pending_returns", 0)
    return pending_returns > 0, pending_returns

